// Release notes generated by dotnet-releaser from the pull requests and commits since the previous tag.
//
//   node scripts/release/notes.mjs <X.Y.Z> [--update]
//
// Without --update it only prints the notes (read-only). With --update it creates or updates the
// GitHub release of the tag vX.Y.Z: ci.yml does this as its very last step, so a release
// exists only once its packages and docs are out.
//
// The repository comes from GITHUB_REPOSITORY (or the `origin` remote): a sandbox or a fork writes its
// own releases. Needs `dotnet-releaser` on PATH (dotnet tool install -g dotnet-releaser) and a token in
// GITHUB_TOKEN (or `gh auth token`).

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { ROOT, fail, parseArgs, parseVersion, run, tryRun } from './lib.mjs';

const args = parseArgs(process.argv.slice(2));
const version = args._[0];
if (!parseVersion(version) || parseVersion(version).pre.length) fail('usage: notes.mjs <X.Y.Z> [--update]');

function repository() {
  if (process.env.GITHUB_REPOSITORY) return process.env.GITHUB_REPOSITORY;
  const url = run('git', ['remote', 'get-url', 'origin']);
  const m = /github\.com[:/]([^/]+)\/(.+?)(?:\.git)?$/.exec(url);
  if (!m) fail(`cannot read the GitHub repository from ${url}`);
  return `${m[1]}/${m[2]}`;
}

const [owner, repo] = repository().split('/');
const template = fs.readFileSync(path.join(ROOT, 'scripts', 'release', 'changelog.toml'), 'utf8');
const config = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'cocoar-notes-')), 'dotnet-releaser.toml');
fs.writeFileSync(config, template.replaceAll('__OWNER__', owner).replaceAll('__REPO__', repo));

const token = process.env.GITHUB_TOKEN || run('gh', ['auth', 'token']);
const cli = ['changelog', '--github-token', token, config, version, ...(args.update ? ['--update'] : [])];
console.log(`dotnet-releaser changelog ${owner}/${repo} ${version}${args.update ? ' --update' : ''}`);
const result = tryRun('dotnet-releaser', cli, { stdio: ['ignore', 'pipe', 'pipe'], env: process.env });
process.stdout.write(`${result.stdout}\n`);
if (result.status !== 0 || /\bERR\b/.test(result.stdout)) {
  if (result.stderr) console.error(result.stderr);
  fail(`dotnet-releaser changelog failed (${result.status})`);
}
